[
  {
    "num": 1,
    "type": "choice",
    "question": "(2025·浙江嘉兴三模·★★)高铁酸钠(Na2FeO4)是一种新型绿色消毒剂,主要用于饮用水处理。工业上制备高铁酸钠的一种方法为 3ClO⁻ + 2Fe³⁺ + 10OH⁻ = 2FeO4²⁻ + 3Cl⁻ + 5H2O,下列说法不正确的是(NA为阿伏加德罗常数的值)",
    "options": {
      "A": "Fe³⁺是还原剂,Cl⁻是还原产物",
      "B": "生成1 mol FeO4²⁻,转移电子的数目为3NA",
      "C": "由反应知,该条件下氧化性:ClO⁻ > FeO4²⁻",
      "D": "Na2FeO4用作消毒剂,是因为FeO4²⁻与水反应后生成了胶体"
    }
  },
  {
    "num": 2,
    "type": "choice",
    "question": "(2025·四川绵阳模拟·★★)二氟化氧(OF2)是极强的氧化剂和氟化剂。已知:①2F2 + 2NaOH = OF2 + 2NaF + H2O(NaOH溶液的浓度为2%),②2OF2 + 2S = SO2 + SF4。下列说法错误的是",
    "options": {
      "A": "OF2分子的空间结构呈V形",
      "B": "反应①中,每生成1 mol OF2,转移4 mol电子",
      "C": "反应②中,SO2和SF4既是氧化产物又是还原产物",
      "D": "氧化性:F2 > OF2 > S"
    }
  },
  {
    "num": 3,
    "type": "choice",
    "question": "(2025·河北模拟预测·★★★)几种离子在水溶液中有如图转化关系。下列说法正确的是",
    "options": {
      "A": "该条件下的氧化性:Ce⁴⁺ > Cr2O7²⁻ > ClO4⁻",
      "B": "反应(1)中,每生成1 mol Cr2O7²⁻,转移3 mol电子",
      "C": "将反应(2)设计成原电池,Cr2O7²⁻在负极发生反应",
      "D": "Ce⁴⁺与ClO3⁻反应生成Ce³⁺和ClO4⁻时,氧化剂与还原剂的物质的量之比为1:2"
    }
  },
  {
    "num": 4,
    "type": "choice",
    "question": "(2025·黑龙江省联考·★★★)稀有气体化合物在化学、照明、医疗等众多领域有广泛应用,含Xe化合物的种类较多,氙的氟化物(XeFn)与NaOH溶液反应剧烈,与水反应则较为温和,反应方程式见下表:\n与水反应\t与NaOH溶液反应\nⅰ. 2XeF2 + 2H2O = 2Xe↑ + O2↑ + 4HF\tⅱ. 2XeF2 + 4OH⁻ = 2Xe↑ + O2↑ + 4F⁻ + 2H2O\nⅲ. XeF6 + 3H2O = XeO3 + 6HF\tⅳ. 2XeF6 + 4Na⁺ + 16OH⁻ = Na4XeO6↓ + Xe↑ + O2↑ + 12F⁻ + 8H2O\n下列说法错误的是",
    "options": {
      "A": "反应ⅰ中XeF2既是氧化剂又是还原剂",
      "B": "反应ⅱ中每生成1 mol O2转移4 mol电子",
      "C": "反应ⅲ中XeF6只作氧化剂",
      "D": "反应ⅳ中Xe元素被氧化和被还原的物质的量之比为1:1"
    }
  }
]
